def dedupe_contacts(rows):
    import re
    from datetime import datetime

    def normalize_name(value):
        value = value.strip()
        if value.isupper() or value.islower():
            return value.title()
        return value

    def normalize_email(value):
        value = value.strip()

        # Use the content inside angle brackets when present.
        match = re.search(r"<([^<>]*)>", value)
        if match:
            value = match.group(1)

        value = value.strip().lower()

        if value.count("@") != 1:
            return ""

        local, domain = value.split("@")
        if domain in {"gmail.com", "googlemail.com"}:
            local = local.split("+", 1)[0].replace(".", "")
            domain = "gmail.com"

        if (
            not local
            or not domain
            or "." not in domain
            or domain.startswith(".")
            or domain.endswith(".")
        ):
            return ""

        return f"{local}@{domain}"

    def normalize_phone(value):
        # Remove an extension and everything following it.
        value = re.split(r"(?i:ext|x|#)", value, maxsplit=1)[0]
        digits = re.sub(r"\D", "", value)

        if len(digits) == 11 and digits.startswith("1"):
            digits = digits[1:]

        if len(digits) != 10 or digits[0] in {"0", "1"}:
            return ""

        return digits

    def normalize_zip(value):
        value = value.strip()

        match = re.fullmatch(r"(\d{5})-\d{4}", value)
        if match:
            value = match.group(1)

        if re.fullmatch(r"\d{4}", value):
            value = "0" + value

        return value if re.fullmatch(r"\d{5}", value) else ""

    def parse_updated(value):
        value = value.strip()
        for fmt in ("%Y-%m-%d", "%m/%d/%Y", "%Y-%m-%dT%H:%M:%S"):
            try:
                return datetime.strptime(value, fmt)
            except ValueError:
                pass
        raise ValueError(f"Invalid updated value: {value!r}")

    def is_opted_out(value):
        return value.strip().lower() in {"y", "yes", "true", "1"}

    normalized_rows = []

    for input_index, row in enumerate(rows):
        email = normalize_email(row["email"])
        phone = normalize_phone(row["phone"])

        # Drop rows lacking both a valid email and a valid phone.
        if not email and not phone:
            continue

        tags = {
            tag.strip().lower()
            for tag in re.split(r"[;,]", row["tags"])
            if tag.strip()
        }

        normalized_rows.append(
            {
                "input_index": input_index,
                "first_name": normalize_name(row["first_name"]),
                "last_name": normalize_name(row["last_name"]),
                "email": email,
                "phone": phone,
                "zip": normalize_zip(row["zip"]),
                "tags": tags,
                "opted_out": is_opted_out(row["opted_out"]),
                "updated_dt": parse_updated(row["updated"]),
                "source": row["source"].strip().lower(),
            }
        )

    count = len(normalized_rows)
    parent = list(range(count))
    size = [1] * count

    def find(index):
        while parent[index] != index:
            parent[index] = parent[parent[index]]
            index = parent[index]
        return index

    def union(a, b):
        root_a = find(a)
        root_b = find(b)

        if root_a == root_b:
            return

        if size[root_a] < size[root_b]:
            root_a, root_b = root_b, root_a

        parent[root_b] = root_a
        size[root_a] += size[root_b]

    email_owner = {}
    phone_last_name_owner = {}

    for index, row in enumerate(normalized_rows):
        if row["email"]:
            previous = email_owner.get(row["email"])
            if previous is None:
                email_owner[row["email"]] = index
            else:
                union(index, previous)

        if row["phone"] and row["last_name"]:
            key = (row["phone"], row["last_name"].casefold())
            previous = phone_last_name_owner.get(key)
            if previous is None:
                phone_last_name_owner[key] = index
            else:
                union(index, previous)

    groups = {}
    for index, row in enumerate(normalized_rows):
        groups.setdefault(find(index), []).append(row)

    def pick_field(group, field):
        candidates = [row for row in group if row[field]]
        if not candidates:
            return ""

        best = max(
            candidates,
            key=lambda row: (
                row["source"] == "manual",
                row["updated_dt"],
                -row["input_index"],
            ),
        )
        return best[field]

    ordered_groups = sorted(
        groups.values(),
        key=lambda group: min(row["input_index"] for row in group),
    )

    result = []

    for group in ordered_groups:
        all_tags = set()
        for row in group:
            all_tags.update(row["tags"])

        latest_updated = max(row["updated_dt"] for row in group)

        result.append(
            {
                "first_name": pick_field(group, "first_name"),
                "last_name": pick_field(group, "last_name"),
                "zip": pick_field(group, "zip"),
                "email": pick_field(group, "email"),
                "phone": pick_field(group, "phone"),
                "source": pick_field(group, "source"),
                "tags": ";".join(sorted(all_tags)),
                "opted_out": (
                    "Y" if any(row["opted_out"] for row in group) else "N"
                ),
                "updated": latest_updated.strftime("%Y-%m-%d"),
            }
        )

    return result
